import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import { useGetBrandsListQuery } from 'entities/Brand';
import { ButtonsBar, OfferDetail, useGetOfferQuery } from 'entities/Offer';
import { useNotFoundError } from 'shared/hooks';
import { OverlayLoader, Page, PageTitle } from 'shared/ui';

interface IOfferProps extends HTMLAttributes<HTMLDivElement> {}

export const Offer: FC<IOfferProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const params = useParams<{ id: string }>();
	const { data: offer, isFetching, error } = useGetOfferQuery(params?.id || '');
	const { data: brands } = useGetBrandsListQuery(`brand_uuid=${offer?.brand?.uuid}`, { skip: !offer?.brand?.uuid });
	const brand = brands?.results?.[0];

	useNotFoundError(error);

	return (
		<Page {...props}>
			<PageTitle component={<ButtonsBar brand={brand} isSinglePage />}>{t('Детали оффера')}</PageTitle>

			{isFetching && <OverlayLoader />}

			<OfferDetail offer={offer} brand={brand} isSinglePage />
		</Page>
	);
};

export default Offer;
